DO $$ BEGIN
 IF (SELECT count(*) FROM fixture_release_changes)<>25 OR (SELECT count(distinct id) FROM fixture_release_changes)<>25 THEN RAISE EXCEPTION 'Wrong change count'; END IF;
 IF (select md5(jsonb_agg(to_jsonb(f) order by id)::text) from public.fixtures f)<>'7c61ac7435b0faa7eaeb0b03d31bd8ba' THEN RAISE EXCEPTION 'Schedule changed; review required'; END IF;
 IF (select md5(jsonb_agg(to_jsonb(r) order by id)::text) from public.result_versions r)<>'fb8afcb4c1e8fe901add297074502ab0' THEN RAISE EXCEPTION 'Results changed; review required'; END IF;
 IF (select md5(coalesce(jsonb_agg(to_jsonb(p) order by id)::text,'[]')) from public.team_kickoff_preferences p)<>'2285a127e6e51ded234a4994436fadf4' THEN RAISE EXCEPTION 'Preferences changed; review required'; END IF;
 IF (select md5(coalesce(jsonb_agg(to_jsonb(n) order by team_id)::text,'[]')) from public.team_fixture_notes n)<>'a8e690f4d2d11529d390e6f907ed7d2c' THEN RAISE EXCEPTION 'Scheduling notes changed; review required'; END IF;
