 IF EXISTS(select 1 from fixture_release_changes c left join public.fixtures f on f.id=c.id left join public.competition_seasons cs on cs.id=f.competition_season_id
 WHERE f.id is null or f.competition_season_id<>c.competition_season_id or cs.lifecycle<>'active' or cs.publication_state<>'published'
 OR f.round_number<>c.round_number or c.round_number<=1 or f.match_date<>c.match_date or f.match_date<current_date
 OR f.schedule_version<>c.schedule_version or f.stage<>'regular_season' or f.publication_state<>'published' or f.schedule_status<>'scheduled'
 OR f.home_team_id<>(c.before->>'home_team_id')::uuid or f.away_team_id<>(c.before->>'away_team_id')::uuid
 OR f.kickoff_time<>(c.before->>'kickoff_time')::time or f.court<>(c.before->>'court')::integer
 OR exists(select 1 from public.result_versions r where r.fixture_id=f.id and r.status='published')) THEN RAISE EXCEPTION 'Target baseline mismatch or completed fixture'; END IF;
END $$;
CREATE TEMP TABLE fixture_release_protected ON COMMIT DROP AS
select 'fixtures'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(f) as row from public.fixtures f where not exists(select 1 from fixture_release_changes c where c.id=f.id)) protected_rows) as hash
UNION ALL
select 'results'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(r) as row from public.result_versions r) protected_rows) as hash
UNION ALL
select 'teams'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(t) as row from public.teams t) protected_rows) as hash
UNION ALL
select 'preferences'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(p) as row from public.team_kickoff_preferences p) protected_rows) as hash
UNION ALL
select 'notes'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(n) as row from public.team_fixture_notes n) protected_rows) as hash
UNION ALL
select 'adjustments'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.standing_adjustments a) protected_rows) as hash
UNION ALL
select 'editions'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(c) as row from public.competition_seasons c) protected_rows) as hash
UNION ALL
select 'other_seasons'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(s) as row from public.seasons s where id<>'ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2') protected_rows) as hash
UNION ALL
select 'old_audit'::text as kind, (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.admin_audit_log a where transaction_id<>txid_current()) protected_rows) as hash;
-- Same temporary unpublish/re-publish mechanism as publish_fixture_change_set.
-- All readers retain the previous committed schedule until this transaction commits.
-- Existing constraints and audit/version triggers remain enabled; no auth identity is impersonated.
UPDATE public.fixtures f SET publication_state='draft' FROM fixture_release_changes c WHERE f.id=c.id;
UPDATE public.fixtures f SET home_team_id=(c.after->>'home_team_id')::uuid,away_team_id=(c.after->>'away_team_id')::uuid,
 kickoff_time=(c.after->>'kickoff_time')::time,court=(c.after->>'court')::integer,publication_state='published'
 FROM fixture_release_changes c WHERE f.id=c.id;
UPDATE public.seasons SET name='2026 - Season 2' WHERE id='ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2';
DO $$ BEGIN
 IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(f) as row from public.fixtures f where not exists(select 1 from fixture_release_changes c where c.id=f.id)) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='fixtures') THEN RAISE EXCEPTION 'Protected fixtures changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(r) as row from public.result_versions r) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='results') THEN RAISE EXCEPTION 'Protected results changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(t) as row from public.teams t) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='teams') THEN RAISE EXCEPTION 'Protected teams changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(p) as row from public.team_kickoff_preferences p) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='preferences') THEN RAISE EXCEPTION 'Protected preferences changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(n) as row from public.team_fixture_notes n) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='notes') THEN RAISE EXCEPTION 'Protected notes changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.standing_adjustments a) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='adjustments') THEN RAISE EXCEPTION 'Protected adjustments changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(c) as row from public.competition_seasons c) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='editions') THEN RAISE EXCEPTION 'Protected editions changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(s) as row from public.seasons s where id<>'ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2') protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='other_seasons') THEN RAISE EXCEPTION 'Protected other_seasons changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.admin_audit_log a where transaction_id<>txid_current()) protected_rows) IS DISTINCT FROM (select hash from fixture_release_protected where kind='old_audit') THEN RAISE EXCEPTION 'Protected old_audit changed; rollback'; END IF;
 IF EXISTS(select 1 from fixture_release_changes c join public.fixtures f on f.id=c.id where
 f.home_team_id<>(c.after->>'home_team_id')::uuid or f.away_team_id<>(c.after->>'away_team_id')::uuid
 or f.kickoff_time<>(c.after->>'kickoff_time')::time or f.court<>(c.after->>'court')::integer
 or f.schedule_version<>c.schedule_version+2 or f.publication_state<>'published' or f.schedule_status<>'scheduled') THEN RAISE EXCEPTION 'Updated fixture mismatch'; END IF;
 IF (select count(*) from public.admin_audit_log where transaction_id=txid_current())<>51 THEN RAISE EXCEPTION 'Expected 51 audited row changes'; END IF;
 IF (select count(*) from public.fixtures where competition_season_id in ('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9'))<>480 THEN RAISE EXCEPTION 'Fixture count changed'; END IF;
END $$;
COMMIT;
SELECT name,starts_on,ends_on FROM public.seasons WHERE id='ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2';

